update vm_sensor_monitor_status
set status = #{item.status},
monitor_time = DATE_FORMAT(#{item.monitorTime}, '%Y-%m-%d %H:%i:%S'),
monitor_desc = #{item.monitorDiscription},
delete_flag = #{item.deleteFlag}
where device_code = #{item.deviceCode}
and monitor_code = #{item.monitorName}

    and sensor_code = #{item.sensorCode}

UPDATE
vm_sensor_monitor_status
set
status = #{item.status},
monitor_time = DATE_FORMAT(#{item.monitorTime}, '%Y-%m-%d %H:%i:%S'),
monitor_desc = #{item.monitorDiscription},
delete_flag = #{item.deleteFlag}
where
device_code = #{item.deviceCode} and monitor_code = #{item.monitorName}

    and sensor_code = #{item.sensorCode}

  and monitor_time <= #{item.monitorTime}

mapper.select:
select count(*) from (select distinct iot.site_code, iot.device_code, iot.device_status as status, iot.latitude as lat, iot.longitude as lon, iot.location, iot.model_code, iot.device_model_code, iot.device_name, iot.province_id, p.area_name as provinceName, iot.city_id, c.area_name as cityName, iot.county_id, co.area_name as countyName from vm_order_sensor_devices d inner join vm_iot_device_t iot on d.device_code = iot.device_code and d.category_code = iot.category_code left join vm_order_customer cust on cust.order_code = d.order_code and cust.industry_code = d.industry_code left join sys_user u on u.user_id = cust.user_id and u.del_flag = '0' left join sys_area p on iot.province_id = p.AREA_CODE left join sys_area c on iot.city_id= c.AREA_CODE left join sys_area co on iot.county_id= co.AREA_CODE
left join vm_organ_device_rel_t rel on d.tenant_id = rel.tenant_id and d.industry_code = rel.industry_code and d.device_code = rel.device_code and rel.device_type in (8,10)
where d.ord_status in (0,1,2) and iot.delete_flag = 0
AND cust.user_id = #{item.userId}
AND d.industry_code = #{item.industryCode}
AND d.tenant_id = #{item.tenantId}
AND iot.site_code in
#{siteCode}
AND iot.province_id = #{item.provinceId}
AND iot.city_id = #{item.cityId}
AND iot.county_id = #{item.countyId}
AND iot.device_code = #{item.deviceCode}
AND iot.device_name like concat('%', #{item.deviceName}, '%')
AND rel.dept_id in
#{item}
AND iot.device_status = #{item.status} ) countNum

