select config_id, config_name, config_key, config_value, config_type, creator, create_time, modifier, update_time, remark
from sys_config
where config_key = #{configKey}

SELECT DISTINCT b.tenant_id AS tenantId, b.tenant_name AS tenantName, b.is_operation AS isOperation, od.app_ver_code, od.industry_code, od.device_code AS deviceCode, b.operation_alarm_type_str AS operationAlarmTypeStr FROM sys_tenant_info b,vm_order_sensor_devices od where od.device_code IN
#{item}
and od.tenant_id = b.tenant_id and od.delete_flag = '0' and od.ord_status in(0, 1, 2) and od.category_code = 2

SELECT COUNT( 1 ) FROM vm_iot_alarm_config_t iac LEFT JOIN vm_iot_alarm_groups_t g on iac.id = g.iot_config_id and g.delete_flag = '0' LEFT JOIN vm_iot_alarm_factor_t iaf ON iaf.group_id = g.id and iaf.delete_flag = '0' LEFT JOIN vm_iot_alarm_device_t iad ON iad.group_id = g.id and iad.delete_flag = '0' where iac.config_status = '1' and iac.delete_flag = '0'
AND iad.device_code in
#{deviceCode}
and iac.tenant_id in
#{tenantId}
